 const string A=@"USB\VID_0001&PID_0001&MI_00\SENTINEL_SYNTHETIC_A",B=@"USB\VID_0001&PID_0002&MI_00\SENTINEL_SYNTHETIC_B";
 [StructLayout(LayoutKind.Sequential)]struct ProbeSecurity{internal int Length;internal IntPtr Descriptor;[MarshalAs(UnmanagedType.Bool)]internal bool Inherit;}
 [DllImport("advapi32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool ConvertStringSecurityDescriptorToSecurityDescriptor(string value,uint revision,out IntPtr descriptor,out uint size);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr CreateJobObject(ref ProbeSecurity security,string name);
 [DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr handle);
