 static void ProbeJobOwner(){string owner=WindowsIdentity.GetCurrent().Owner.Value;Console.WriteLine("OWNER_TRUSTED "+(owner=="S-1-5-18"||owner=="S-1-5-32-544"));foreach(string label in new[]{"explicit_system","default_owner","default_owner_named_local","default_owner_named_global"}){IntPtr descriptor;uint size;if(!ConvertStringSecurityDescriptorToSecurityDescriptor((label=="explicit_system"?"O:SYG:SY":"")+"D:P(A;;GA;;;SY)(A;;GA;;;BA)",1,out descriptor,out size)){Console.WriteLine("JOB_PROBE "+label+" descriptor_error "+Marshal.GetLastWin32Error());continue;}try{var security=new ProbeSecurity{Length=Marshal.SizeOf(typeof(ProbeSecurity)),Descriptor=descriptor,Inherit=false};string jobName=label=="default_owner_named_local"?@"Local\SentinelUsbExactProbe-"+Guid.NewGuid().ToString("N"):label=="default_owner_named_global"?@"Global\SentinelUsbExactProbe-"+Guid.NewGuid().ToString("N"):null;IntPtr job=CreateJobObject(ref security,jobName);int code=Marshal.GetLastWin32Error();try{Console.WriteLine("JOB_PROBE "+label+" success "+(job!=IntPtr.Zero)+" win32 "+(job==IntPtr.Zero?code:0));}finally{if(job!=IntPtr.Zero)CloseHandle(job);}}finally{LocalFree(descriptor);}}}
 static UsbExactBlockFileStore WaitStore(string path){var timer=System.Diagnostics.Stopwatch.StartNew();while(true)try{return new UsbExactBlockFileStore(path);}catch(IOException error){int code=error.HResult&65535;if((code!=32&&code!=33)||timer.ElapsedMilliseconds>=195000)throw;System.Threading.Thread.Sleep(250);}}
 static void Fixture(UsbExactBlockState.Snapshot value){if(value==null)return;Check(value.OwnerSid==WindowsIdentity.GetCurrent().User.Value);foreach(string id in value.Blocked)Check(id==A||id==B);}
 static void Check(bool ok){if(!ok)throw new InvalidOperationException("Backend qualification refused");}
 static FileSecurity Security(){var acl=new FileSecurity();acl.SetOwner(new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid,null));acl.SetAccessRuleProtection(true,false);foreach(var sid in new[]{WellKnownSidType.LocalSystemSid,WellKnownSidType.BuiltinAdministratorsSid})acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid,null),FileSystemRights.FullControl,AccessControlType.Allow));return acl;}
 static byte[] Worker(){using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream("Sentinel.Exact.Worker")){Check(input!=null&&input.Length>0&&input.Length<=67108864);using(var memory=new MemoryStream()){input.CopyTo(memory);return memory.ToArray();}}}
 static string Install(){SentinelPolicyDirectory.Provision(UsbExactBlockRecoveryTasks.CodeRoot);using(var pin=new UsbExactBlockFileStore(UsbExactBlockRecoveryTasks.CodeRoot)){string manifest=Path.Combine(UsbExactBlockRecoveryTasks.CodeRoot,"exact-worker.manifest");byte[] bytes=Worker();string hash;using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();string target=Path.Combine(UsbExactBlockRecoveryTasks.CodeRoot,UsbExactBlockRecoveryTasks.ImageName(hash));if(File.Exists(manifest)){using(var file=new FileStream(manifest,FileMode.Open,FileAccess.Read,FileShare.Read)){Check(file.Length==107);var existingData=new byte[107];int read=0;while(read<existingData.Length){int count=file.Read(existingData,read,existingData.Length-read);Check(count>0);read+=count;}string text=System.Text.Encoding.ASCII.GetString(existingData);Check(System.Text.RegularExpressions.Regex.IsMatch(text,@"\ASNTEXW01\n"+hash+@"\n[0-9a-f]{32}\n\z"));}return hash;}Check(!File.Exists(target));using(var file=new FileStream(target,FileMode.CreateNew,FileSystemRights.Read|FileSystemRights.Write,FileShare.None,4096,FileOptions.WriteThrough,Security())){file.Write(bytes,0,bytes.Length);file.Flush(true);}var info=new FileInfo(target);Check((info.Attributes&FileAttributes.ReparsePoint)==0);using(var file=new FileStream(target,FileMode.Open,FileAccess.Read,FileShare.Read))using(var sha=SHA256.Create())Check(BitConverter.ToString(sha.ComputeHash(file)).Replace("-","").ToLowerInvariant()==hash);byte[] data=System.Text.Encoding.ASCII.GetBytes("SNTEXW01\n"+hash+"\n"+Guid.NewGuid().ToString("N")+"\n");Check(data.Length==107);using(var file=new FileStream(manifest,FileMode.CreateNew,FileSystemRights.Read|FileSystemRights.Write,FileShare.None,4096,FileOptions.WriteThrough,Security())){file.Write(data,0,data.Length);file.Flush(true);}return hash;}}
 static UsbExactBlockState.Request Request(string action,UsbExactBlockState.Snapshot before,string[] after,string[] target){var now=DateTime.UtcNow;return new UsbExactBlockState.Request(action,before,new UsbExactBlockState.Snapshot(before==null?1:before.Generation+1,WindowsIdentity.GetCurrent().User.Value,after),target,Guid.NewGuid().ToString("N"),new string('a',64),now,now.AddMinutes(5));}
 static void Prepare(UsbExactBlockFileStore store,UsbExactBlockBackend backend,UsbExactBlockState.Request request){store.WritePrepared(request);backend.PrepareIndependentRecovery(request);backend.VerifyIndependentRecovery(request);store.AdvancePending(request.Digest,UsbExactBlockState.Stage.Prepared,UsbExactBlockState.Stage.RecoveryArmed);}
 static void Apply(UsbExactBlockFileStore store,UsbExactBlockBackend backend,UsbExactBlockState.Request request,bool commit){Prepare(store,backend,request);backend.ApplyCandidate(request);store.AdvancePending(request.Digest,UsbExactBlockState.Stage.RecoveryArmed,UsbExactBlockState.Stage.Applied);backend.VerifyPolicy(request.After);store.AdvancePending(request.Digest,UsbExactBlockState.Stage.Applied,UsbExactBlockState.Stage.PolicyVerified);if(commit)store.CommitCandidate(request.Digest,request.Before,request.After);}
 static void Retire(UsbExactBlockFileStore store,UsbExactBlockBackend backend,UsbExactBlockState.Request request){backend.StopProducersAndVerifyQuiescent(request);backend.VerifyPolicy(store.ReadCommitted());backend.RetireIndependentRecovery(request);store.RetirePending(request.Digest);Check(store.ReadPending()==null);}
 static void Commit(UsbExactBlockFileStore store,UsbExactBlockBackend backend,UsbExactBlockState.Request request){Apply(store,backend,request,true);store.AdvancePending(request.Digest,UsbExactBlockState.Stage.PolicyVerified,UsbExactBlockState.Stage.Committed);Retire(store,backend,request);}
 [STAThread]public static int Main(string[] args){if(args.Length!=1||args[0]!="--private-backend")return 2;if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))return 3;int stage=1;try{ProbeJobOwner();DuckyWorkerJob.AttachCurrentWorker();SentinelPolicyDirectory.Provision(UsbExactBlockRecoveryTasks.CodeRoot);using(var rootPin=new UsbExactBlockFileStore(UsbExactBlockRecoveryTasks.CodeRoot))SentinelPolicyDirectory.Provision(UsbExactBlockBackend.StateRoot);using(var before=WaitStore(UsbExactBlockBackend.StateRoot))Fixture(before.ReadCommitted());string hash=Install();using(var store=WaitStore(UsbExactBlockBackend.StateRoot))using(var backend=new UsbExactBlockBackend(store,hash)){var interrupted=store.ReadPending();if(interrupted!=null){var r=interrupted.Request;Fixture(r.Before);Fixture(r.After);foreach(string id in r.Targets)Check(id==A||id==B);var decision=store.ClaimRecovery(r.Digest);Fixture(decision);backend.StopProducersAndVerifyQuiescent(r);if(UsbExactBlockState.Same(decision,r.Before))backend.RestoreBefore(r);else Check(UsbExactBlockState.Same(decision,r.After));backend.VerifyPolicy(decision);backend.RetireIndependentRecovery(r);store.RetirePending(r.Digest);Check(store.ReadPending()==null);Console.WriteLine("PASS authenticated interrupted synthetic transaction recovery before retry");}var initial=store.ReadCommitted();Fixture(initial);backend.VerifyPolicy(initial);if(initial!=null&&initial.Blocked.Length!=0){var cleanup=Request("allow",initial,new string[0],initial.Blocked);Commit(store,backend,cleanup);initial=cleanup.After;}stage=2;var first=Request("block",initial,new[]{A},new[]{A});Commit(store,backend,first);stage=3;var second=Request("block",first.After,new[]{A,B},new[]{B});Commit(store,backend,second);stage=4;var allow=Request("allow",second.After,new[]{B},new[]{A});Commit(store,backend,allow);Console.WriteLine("PASS actual suspended worker apply, task preparation, multi-block target preservation and external retirement");stage=5;var pending=Request("block",allow.After,new[]{A,B},new[]{A});Apply(store,backend,pending,false);backend.DispatchRecoveryForQualification(pending);Check(UsbExactBlockState.Same(store.ReadCommitted(),allow.After));backend.VerifyPolicy(allow.After);Retire(store,backend,pending);Console.WriteLine("PASS actual SYSTEM recovery restores precommit policy while retaining prior committed block");stage=6;var post=Request("block",allow.After,new[]{A,B},new[]{A});Apply(store,backend,post,true);backend.DispatchRecoveryForQualification(post);Check(UsbExactBlockState.Same(store.ReadCommitted(),post.After));backend.VerifyPolicy(post.After);Retire(store,backend,post);Console.WriteLine("PASS actual SYSTEM recovery preserves candidate after ambiguous commit reply");stage=7;var removeA=Request("allow",post.After,new[]{B},new[]{A});Commit(store,backend,removeA);var final=Request("allow",removeA.After,new string[0],new[]{B});Commit(store,backend,final);Check(store.ReadCommitted().Blocked.Length==0);Console.WriteLine("PASS full private exact backend qualification; NO Hello authority, live DeviceInstall, device action or reboot claim");return 0;}}catch(Exception error){Console.WriteLine("FAIL exact backend stage "+stage+" category "+error.GetType().Name+" hresult "+error.HResult.ToString("X8"));for(int depth=0;error!=null&&depth<6;depth++,error=error.InnerException){string reason="foreign_message_withheld";switch(error.Message){case "Exact parent job security failed":case "Exact parent job create failed":case "Exact parent job already exists":case "Exact parent job limit failed":case "Exact suspended child create failed":case "Exact suspended child assignment failed":case "Exact suspended child resume failed":case "Exact producer failed":case "Exact producer descendants remain":case "Exact native backend refused":case "Exact recovery task refused":case "Local policy operation failed":case "Protected exact-block store refused":case "Saved baseline changed":case "Exact saved/effective readback differs":reason=error.Message;break;}string site=error.TargetSite==null?"none":error.TargetSite.Name;if(!System.Text.RegularExpressions.Regex.IsMatch(site,@"\A[A-Za-z0-9_]{1,100}\z"))site="withheld";Console.WriteLine("TRACE "+depth+" "+string.Join(" > ",Array.FindAll((error.StackTrace??"").Split(new[]{Environment.NewLine},StringSplitOptions.RemoveEmptyEntries),line=>line.Contains("UsbExactBlock")||line.Contains("SentinelPolicyDirectory"))));Console.WriteLine("CAUSE "+depth+" "+error.GetType().Name+" "+error.HResult.ToString("X8")+" site "+site+" reason "+reason);var native=error as System.ComponentModel.Win32Exception;if(native!=null)Console.WriteLine("WIN32 "+native.NativeErrorCode); }return 1;}}
